import sys

MOD = 10**9 + 7

def count_valid_originals(words):
    def remove_one_letter(word):
        return [word[:i] + word[i+1:] for i in range(len(word))]

    dp = [[0] * (len(words) + 1) for _ in range(len(words))]
    dp[0][1] = 1

    for i in range(1, len(words)):
        for j in range(1, i + 2):
            for prev_word in remove_one_letter(words[i - 1]):
                for k in range(j):
                    if all(remove_one_letter(words[i]) >= [prev_word]):
                        dp[i][j] += dp[i - 1][k]
                        dp[i][j] %= MOD

    return sum(dp[-1]) % MOD

n = int(sys.stdin.readline().strip())
words = [sys.stdin.readline().strip() for _ in range(n)]

print(count_valid_originals(words))
